#!/usr/bin/env python3
"""AURORA-FP persona header 生成器。
从 persona.json 读取引擎级指纹配置，输出编译期 C++ header。
由 CI 在 gn gen 前执行；本地开发也可运行。"""
import json, sys, os

def main():
    if len(sys.argv) < 3:
        print("用法: gen_persona_header.py <persona.json> <output.h>", file=sys.stderr)
        sys.exit(1)
    with open(sys.argv[1]) as f:
        p = json.load(f)
    gpu = p.get("gpu", {})
    hw  = p.get("hardware", {})
    ch  = p.get("client_hints", {})

    def safe(s):
        return s.replace('\\', '\\\\').replace('"', '\\"').replace('\n', '\\n')

    lines = [
        "/* AUTO-GENERATED by AURORA-FP persona header generator. DO NOT EDIT. */",
        "#ifndef AURORA_PERSONA_H_",
        "#define AURORA_PERSONA_H_",
        "",
        "#include <cstdint>",
        "",
        "// AURORA-FP F1: WebGL UNMASKED_VENDOR/RENDERER override",
        f'[[maybe_unused]] static constexpr char kAuroraGLVendor[]     = "{safe(gpu.get("gl_vendor", ""))}";',
        f'[[maybe_unused]] static constexpr char kAuroraGLRenderer[]   = "{safe(gpu.get("gl_renderer", ""))}";',
        f'[[maybe_unused]] static constexpr char kAuroraGLVersion[]    = "{safe(gpu.get("gl_version", ""))}";',
        f'[[maybe_unused]] static constexpr char kAuroraGLDeviceName[] = "{safe(gpu.get("device_name", ""))}";',
        "",
        "// AURORA-FP F5: WebGPU adapter info",
        f'[[maybe_unused]] static constexpr char kAuroraWGVendor[]     = "{safe(gpu.get("gl_vendor", ""))}";',
        f'[[maybe_unused]] static constexpr char kAuroraWGArch[]       = "{safe(ch.get("architecture", "x86"))}";',
        "",
        "// AURORA-FP F6: navigator.hardware",
        f'[[maybe_unused]] static constexpr uint32_t kAuroraDeviceMemory     = {hw.get("deviceMemory", 8)};',
        f'[[maybe_unused]] static constexpr uint32_t kAuroraHardwareConcurrency = {hw.get("hardwareConcurrency", 8)};',
        "",
        "// AURORA-FP F3/F4: 固定种子（canvas/audio 微扰用，跨会话恒定）",
        f'[[maybe_unused]] static constexpr uint64_t kAuroraCanvasSeed = {int.from_bytes(__import__("hashlib").sha256(gpu.get("canvas_seed","seed").encode()).digest()[:8], "big") & 0x7FFFFFFFFFFFFFFF}ULL;',
        f'[[maybe_unused]] static constexpr uint64_t kAuroraAudioSeed = {int.from_bytes(__import__("hashlib").sha256(gpu.get("audio_seed","aseed").encode()).digest()[:8], "big") & 0x7FFFFFFFFFFFFFFF}ULL;',
        "",
        "// AURORA-FP F8: Client Hints",
        f'[[maybe_unused]] static constexpr char kAuroraPlatform[]     = "{safe(hw.get("platform", "Win32"))}";',
        f'[[maybe_unused]] static constexpr char kAuroraArch[]         = "{safe(ch.get("architecture", "x86"))}";',
        f'[[maybe_unused]] static constexpr char kAuroraBitness[]      = "{safe(ch.get("bitness", "64"))}";',
        f'[[maybe_unused]] static constexpr char kAuroraPlatformVersion[] = "{safe(ch.get("platformVersion", "15.0.0"))}";',
        "",
        "#endif  // AURORA_PERSONA_H_",
    ]
    os.makedirs(os.path.dirname(os.path.abspath(sys.argv[2])), exist_ok=True)
    with open(sys.argv[2], 'w') as f:
        f.write('\n'.join(lines) + '\n')
    print(f"persona header 生成: {sys.argv[2]}")

if __name__ == '__main__':
    main()
